const menuButton=document.querySelector('#menu-toggle');
const nav=document.querySelector('#main-nav');
menuButton?.addEventListener('click',()=>{const expanded=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(expanded));menuButton.setAttribute('aria-label',expanded?'Đóng menu':'Mở menu');nav.classList.toggle('open',expanded)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Mở menu');menuButton.focus()}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-type]').forEach(item=>{item.hidden=button.dataset.filter!=='all'&&item.dataset.type!==button.dataset.filter})}));
const lightbox=document.querySelector('#lightbox');
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{lightbox.querySelector('img').src=button.dataset.photo;lightbox.querySelector('img').alt=button.dataset.caption;lightbox.querySelector('p').textContent=button.dataset.caption;lightbox.showModal()}));
lightbox?.querySelector('.close').addEventListener('click',()=>lightbox.close());
lightbox?.addEventListener('click',e=>{if(e.target===lightbox){const r=lightbox.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)lightbox.close()}});
const normalize=s=>s.toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
document.querySelector('#article-search')?.addEventListener('input',e=>{let count=0;document.querySelectorAll('[data-search]').forEach(card=>{card.hidden=!normalize(card.dataset.search).includes(normalize(e.target.value.trim()));if(!card.hidden)count++});document.querySelector('#no-results').hidden=count>0});
const form=document.querySelector('#request-form');
if(form&&new URLSearchParams(location.search).get('nhucau')==='bao-gia')document.querySelector('#need').value='Nhận báo giá theo lô';
form?.addEventListener('submit',e=>{e.preventDefault();const message=`Xin chào, gia đình tôi muốn ${document.querySelector('#need').value.toLocaleLowerCase('vi')} tại Lạc Hồng Viên.\nLoại khuôn viên: ${document.querySelector('#type').value}.\n${document.querySelector('#note').value.trim()}\nNhờ tư vấn viên trao đổi và xác nhận thông tin giúp gia đình. Xin cảm ơn.`;document.querySelector('#request-text').textContent=message;document.querySelector('#request-result').hidden=false;document.querySelector('#request-result').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});document.querySelector('#copy-status').textContent='Nội dung chưa được gửi. Bạn có thể sao chép để tự gửi hoặc gọi hotline.'});
document.querySelector('#copy-request')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#request-text').textContent);document.querySelector('#copy-status').textContent='Đã sao chép. Bạn có thể dán vào kênh nhắn tin đang sử dụng.'}catch{document.querySelector('#copy-status').textContent='Trình duyệt chưa cho phép sao chép. Bạn hãy chọn và sao chép đoạn nội dung phía trên.'}});
